<?php
require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/blockchain.php';
$user=require_role('student');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['registration_id']??0);$s=db()->prepare("SELECT r.*,e.reg_deadline FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.id=? AND r.user_id=? AND r.status<>'Cancelled'");$s->execute([$id,$user['id']]);$r=$s->fetch();if($r&&strtotime($r['reg_deadline'])>=time()){db()->prepare("UPDATE registrations SET status='Cancelled' WHERE id=?")->execute([$id]);flash('success','Your registration was cancelled.');}else flash('warning','This registration can no longer be cancelled.');redirect('student/my_registrations.php');}
$s=db()->prepare('SELECT r.*,e.title,e.event_date,e.start_time,e.venue,e.reg_deadline FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? ORDER BY r.created_at DESC');$s->execute([$user['id']]);$rows=$s->fetchAll();$pageTitle='My registrations';require dirname(__DIR__).'/includes/header.php';
?>
<div class="mb-4"><p class="text-primary text-uppercase small fw-bold mb-1">Your event passbook</p><h1 class="h2 fw-bold">My registrations</h1></div>
<?php foreach($rows as $r):$v=verify_registration((int)$r['id'],false);?><div class="card p-4 mb-3"><div class="row align-items-center g-3"><div class="col-md-5"><h2 class="h5 fw-bold mb-1"><?=e($r['title'])?></h2><div class="small text-secondary"><?=e(date('M j, Y',strtotime($r['event_date'])))?> · <?=e($r['venue'])?></div><div class="small mt-2">Registration #<?=e((string)$r['id'])?> · <span class="badge <?=$r['status']==='Verified'?'text-bg-success':($r['status']==='Rejected'?'text-bg-danger':($r['status']==='Cancelled'?'text-bg-secondary':'text-bg-warning'))?>"><?=e($r['status'])?></span></div></div><div class="col-md-4"><?php if($v['secure']):?><span class="badge status-secure p-2"><i class="bi bi-shield-check"></i> Protected · block #<?=e((string)$v['block']['id'])?> · <?=e(substr($v['block']['block_hash'],0,10))?>…</span><?php else:?><span class="badge bg-danger p-2">⚠ Not secured / integrity issue</span><?php endif;?></div><div class="col-md-3 d-flex flex-wrap gap-2"><a class="btn btn-sm btn-outline-primary" href="<?=e(url('student/verify.php?id='.(int)$r['id']))?>">Verify</a><?php if($r['status']!=='Cancelled'&&strtotime($r['reg_deadline'])>=time()):?><form method="post"><?=csrf_field()?><input type="hidden" name="registration_id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Cancel this registration?">Cancel</button></form><?php endif;?></div></div></div><?php endforeach;?><?php if(!$rows):?><div class="card empty-state">No registrations yet. <a href="<?=e(url('student/events.php'))?>">Find an event</a>.</div><?php endif;?>
<?php require dirname(__DIR__).'/includes/footer.php';?>
